import click
from click.testing import CliRunner
import pytest


@pytest.fixture
def runner():
    return CliRunner()


def test_missing_required_flag(runner):
    @click.command()
    @click.option("--flag", is_flag=True, required=True)
    def cmd(flag):
        pass

    result = runner.invoke(cmd)
    assert result.exit_code == 2
    assert "Error: Missing option '--flag'." in result.output


def test_required_flag_given(runner):
    @click.command()
    @click.option("--flag", is_flag=True, required=True)
    def cmd(flag):
        click.echo(f"flag={flag}")

    result = runner.invoke(cmd, ["--flag"])
    assert result.exit_code == 0
    assert result.output == "flag=True\n"


def test_required_flag_with_explicit_default(runner):
    @click.command()
    @click.option("--flag", is_flag=True, required=True, default=False)
    def cmd(flag):
        click.echo(f"flag={flag}")

    result = runner.invoke(cmd, [])
    assert result.exit_code == 0
    assert result.output == "flag=False\n"


def test_required_bool_flag_pair(runner):
    @click.command()
    @click.option("--on/--off", required=True)
    def cmd(on):
        click.echo(f"on={on}")

    result = runner.invoke(cmd, [])
    assert result.exit_code == 2
    assert "Error: Missing option '--on'." in result.output

    result = runner.invoke(cmd, ["--off"])
    assert result.exit_code == 0
    assert result.output == "on=False\n"


def test_required_flag_multiple(runner):
    @click.command()
    @click.option("--flag", is_flag=True, multiple=True, required=True)
    def cmd(flag):
        click.echo(repr(flag))

    result = runner.invoke(cmd, [])
    assert result.exit_code == 2
    assert "Error: Missing option '--flag'." in result.output
